package crypt

import (
	"bytes"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"testing"
)

// Independent known-answer vectors, measured with the unmodified original
// Cipher export, not generated by this implementation. See doc/review-20261121.md.
func TestAntiOriginalCipherVectors(t *testing.T) {
	data, err := os.ReadFile("testdata/anti-vectors.txt")
	if err != nil {
		t.Fatal(err)
	}
	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		fields := strings.Fields(line)
		typ, err := strconv.ParseUint(fields[0], 16, 32)
		if err != nil {
			t.Fatal(err)
		}
		seed := uint64(0x039e3fdc)
		if len(fields) == 5 {
			seed, err = strconv.ParseUint(fields[3], 16, 32)
			if err != nil {
				t.Fatal(err)
			}
		}
		input, err := hex.DecodeString(fields[len(fields)-1])
		if err != nil {
			t.Fatal(err)
		}
		t.Run(fmt.Sprintf("type%d_len%d_seed%x", typ, len(input), seed), func(t *testing.T) {
			err := decryptAntiPayload(uint32(typ), uint32(seed), input)
			if err != nil {
				t.Fatal(err)
			}
			want := make([]byte, len(input))
			for i := range want {
				want[i] = byte(i)
			}
			if !bytes.Equal(input, want) {
				t.Fatalf("got %x, want %x", input, want)
			}
		})
	}
}

func TestAntiRejectsUnknownCipher(t *testing.T) {
	for _, typ := range []uint32{0, 20, 0xffffffff} {
		if err := decryptAntiPayload(typ, 0, make([]byte, 32)); !errors.Is(err, ErrUnsupportedAntiCipher) {
			t.Fatalf("type %d: got %v", typ, err)
		}
	}
}

// Generated by the unmodified original Cipher export with four seeds, all
// residual lengths and zero, all-one, ascending and mixed-bit plaintexts.
func TestAntiNewDESAndMMBOriginalPatterns(t *testing.T) {
	data, err := os.ReadFile("testdata/anti-newdes-mmb-vectors.txt")
	if err != nil {
		t.Fatal(err)
	}
	for i, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 6 || fields[3] != "1" {
			t.Fatalf("line %d: invalid oracle vector", i+1)
		}
		typ, err := strconv.ParseUint(fields[0], 16, 32)
		if err != nil || (typ != 2 && typ != 9) {
			t.Fatalf("line %d: invalid cipher type", i+1)
		}
		seed, err := strconv.ParseUint(fields[1], 16, 32)
		if err != nil {
			t.Fatal(err)
		}
		length, err := strconv.ParseUint(fields[2], 16, 32)
		if err != nil {
			t.Fatal(err)
		}
		var values [2][]byte
		for j := range values {
			if fields[4+j] != "-" {
				values[j], err = hex.DecodeString(fields[4+j])
				if err != nil {
					t.Fatal(err)
				}
			}
			if uint64(len(values[j])) != length {
				t.Fatalf("line %d: length mismatch", i+1)
			}
		}
		if err := decryptAntiPayload(uint32(typ), uint32(seed), values[1]); err != nil {
			t.Fatalf("line %d: %v", i+1, err)
		}
		if !bytes.Equal(values[0], values[1]) {
			t.Fatalf("line %d type%d seed%x: got %x, want %x", i+1, typ, seed, values[1], values[0])
		}
	}
}

// Direct-key oracle vectors exercise all 64 MMB schedule selectors with mixed
// key words, plus NewDES keys independent of GenKey. Plaintexts include zeros,
// all ones, individual bits and mixed bits across three complete blocks.
func TestAntiNewDESAndMMBOriginalKeys(t *testing.T) {
	data, err := os.ReadFile("testdata/anti-newdes-mmb-keys.txt")
	if err != nil {
		t.Fatal(err)
	}
	for i, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 4 || (fields[0] != "02" && fields[0] != "09") {
			t.Fatalf("line %d: invalid direct-key vector", i+1)
		}
		var values [3][]byte
		for j := range values {
			values[j], err = hex.DecodeString(fields[j+1])
			if err != nil {
				t.Fatalf("line %d: %v", i+1, err)
			}
		}
		if len(values[0]) != 16 || len(values[1]) != 48 || len(values[2]) != 48 {
			t.Fatalf("line %d: invalid key or block length", i+1)
		}
		if fields[0] == "02" {
			decryptAntiNewDES(values[0], values[2])
		} else {
			decryptAntiMMB(values[0], values[2])
		}
		if !bytes.Equal(values[1], values[2]) {
			t.Fatalf("line %d type%s: got %x, want %x", i+1, fields[0], values[2], values[1])
		}
	}
}

// These vectors use arbitrary keys, zero and single-bit plaintexts, and random
// mixed-bit plaintexts. They check every bit of every tail length independently
// of the block ciphers and of our key derivation.
func TestAntiBoxOriginalVectors(t *testing.T) {
	data, err := os.ReadFile("testdata/anti-box-vectors.txt")
	if err != nil {
		t.Fatal(err)
	}
	for i, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 3 {
			t.Fatalf("line %d: expected key/plaintext/ciphertext", i+1)
		}
		var values [3][]byte
		for j := range values {
			values[j], err = hex.DecodeString(fields[j])
			if err != nil {
				t.Fatalf("line %d: %v", i+1, err)
			}
		}
		decryptAntiBoxTail(values[0], values[2])
		if !bytes.Equal(values[1], values[2]) {
			t.Fatalf("line %d: got %x, want %x", i+1, values[2], values[1])
		}
	}
}

// Independent NSEA vectors also cover zero, all-one and mixed-bit blocks, so
// matching the ascending-byte vectors cannot hide CBC or byte-order mistakes.
func TestAntiNSEAOriginalPatterns(t *testing.T) {
	data, err := os.ReadFile("testdata/anti-nsea-vectors.txt")
	if err != nil {
		t.Fatal(err)
	}
	for i, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		fields := strings.Fields(line)
		if len(fields) != 3 {
			t.Fatalf("line %d: expected seed/plaintext/ciphertext", i+1)
		}
		seed, err := strconv.ParseUint(fields[0], 16, 32)
		if err != nil {
			t.Fatal(err)
		}
		want, err := hex.DecodeString(fields[1])
		if err != nil {
			t.Fatal(err)
		}
		got, err := hex.DecodeString(fields[2])
		if err != nil {
			t.Fatal(err)
		}
		if err := decryptAntiPayload(10, uint32(seed), got); err != nil {
			t.Fatal(err)
		}
		if !bytes.Equal(got, want) {
			t.Fatalf("line %d: got %x, want %x", i+1, got, want)
		}
	}
}
